insert into public.programs (id, code, name, short_name, description, accent, glyph) values
  ('ecele', 'ECELE', 'Electronics and Communications Engineering Licensure Examination', 'Electronics & Communications Engineering', 'The PRC board exam for Electronics and Communications Engineers. Master circuits, devices, electromagnetics and communications.', 'indigo', '📡'),
  ('ectle', 'ECTLE', 'Electronics Engineering Technician Licensure Examination', 'Electronics Engineering Technician', 'The PRC board exam for Electronics Engineering Technicians. Build hands-on mastery of devices, digital systems, troubleshooting and safety.', 'cyan', '🔧')
insert into public.subjects (id, program_id, name, code, description, glyph) values
  ('ecele-math', 'ecele', 'Mathematics', 'MATH', 'Algebra, trigonometry, calculus and statistics.', '∑'),
  ('ecele-electronics', 'ecele', 'Electronics', 'ELEC', 'Devices, amplifier circuits and digital logic.', '⚡'),
  ('ecele-emag', 'ecele', 'Electromagnetics', 'EMAG', 'Fields, waves, transmission lines and antennas.', '〰️'),
  ('ecele-comm', 'ecele', 'Communications', 'COMM', 'Analog and digital communication systems and networks.', '📶'),
  ('ecele-circuits', 'ecele', 'Circuit Analysis', 'CIRCUIT', 'DC and AC network analysis.', '🔌'),
  ('ecele-econ', 'ecele', 'Engineering Economics & Management', 'ECON', 'Interest, cash flow, law and professional ethics.', '📊'),
  ('ectle-basics', 'ectle', 'Basic Electronics', 'BASICS', 'Components, symbols, diodes and transistors.', '🧰'),
  ('ectle-digital', 'ectle', 'Digital Electronics', 'DIGITAL', 'Logic gates, Boolean algebra and number systems.', '🔢'),
  ('ectle-electrical', 'ectle', 'Electrical Circuits & Measurements', 'ELEC', 'DC/AC circuits, meters and electrical power.', '🔋'),
  ('ectle-comm', 'ectle', 'Communications Systems', 'COMM', 'Radio, modulation and basic data networks.', '📻'),
  ('ectle-industrial', 'ectle', 'Industrial Electronics', 'INDUSTRIAL', 'Motors, relays, PLCs, safety and troubleshooting.', '🏭'),
  ('ectle-practical', 'ectle', 'Practical Applications', 'PRACTICAL', 'Soldering, assembly and test instruments.', '🛠️')
insert into public.topics (id, subject_id, program_id, name, description) values
  ('ecele-math-algebra', 'ecele-math', 'ecele', 'Algebra & Trigonometry', 'Logs, complex numbers and identities'),
  ('ecele-math-calculus', 'ecele-math', 'ecele', 'Calculus & Statistics', 'Derivatives, integrals and data analysis'),
  ('ecele-el-devices', 'ecele-electronics', 'ecele', 'Devices & Circuits', 'Diodes, BJTs and amplifier basics'),
  ('ecele-el-digital', 'ecele-electronics', 'ecele', 'Digital Logic', 'Gates, Boolean algebra and numbering'),
  ('ecele-em-fields', 'ecele-emag', 'ecele', 'Fields & Waves', 'Electromagnetic fundamentals and propagation'),
  ('ecele-em-transmission', 'ecele-emag', 'ecele', 'Transmission Lines & Antennas', 'Line parameters, matching and antennas'),
  ('ecele-comm-analog', 'ecele-comm', 'ecele', 'Analog Communications', 'AM, FM and sampling'),
  ('ecele-comm-digital', 'ecele-comm', 'ecele', 'Digital Communications & Networks', 'Coding, error rates and IP networking'),
  ('ecele-ckt-dc', 'ecele-circuits', 'ecele', 'DC Circuits', 'Ohm’s law, resistors and network theorems'),
  ('ecele-ckt-ac', 'ecele-circuits', 'ecele', 'AC Circuits', 'Phasors, RMS, resonance and power'),
  ('ecele-econ-interest', 'ecele-econ', 'ecele', 'Interest & Cash Flow', 'Simple interest, annuities and present worth'),
  ('ecele-econ-ethics', 'ecele-econ', 'ecele', 'Law & Professional Ethics', 'Code of ethics and engineering practice'),
  ('ectle-basics-components', 'ectle-basics', 'ectle', 'Components & Symbols', 'Resistors, capacitors and inductors'),
  ('ectle-basics-semi', 'ectle-basics', 'ectle', 'Diodes & Transistors', 'PN junction, Zener and BJT operation'),
  ('ectle-dig-logic', 'ectle-digital', 'ectle', 'Logic Gates & Boolean Algebra', 'AND, OR, NOT and De Morgan’s theorem'),
  ('ectle-dig-systems', 'ectle-digital', 'ectle', 'Number Systems & Memory', 'Binary, hex and basic memory devices'),
  ('ectle-elec-dc', 'ectle-electrical', 'ectle', 'DC Circuits & Measurements', 'Series/parallel circuits and meters'),
  ('ectle-elec-ac', 'ectle-electrical', 'ectle', 'AC Circuits & Power', 'Mains power, RMS and power factor'),
  ('ectle-comm-radio', 'ectle-comm', 'ectle', 'Radio & Modulation', 'Carrier, AM/FM and antenna basics'),
  ('ectle-comm-data', 'ectle-comm', 'ectle', 'Data & Networks', 'Cabling, connectors and OSI layers'),
  ('ectle-ind-control', 'ectle-industrial', 'ectle', 'Control Systems & Motors', 'Relays, contactors, motors and PLCs'),
  ('ectle-ind-safety', 'ectle-industrial', 'ectle', 'Safety & Troubleshooting', 'Grounding, fuses and fault finding'),
  ('ectle-prac-soldering', 'ectle-practical', 'ectle', 'Soldering & Assembly', 'Solder joints, tools and component orientation'),
  ('ectle-prac-instruments', 'ectle-practical', 'ectle', 'Test Instruments', 'Multimeters, scopes and signal generators')
insert into public.questions (id, program_id, subject_id, topic_id, prompt, options, answer_index, explanation, difficulty) values
  ('ecele-math-algebra-q1', 'ecele', 'ecele-math', 'ecele-math-algebra', 'If log₂(x) = 5, what is the value of x?', '["10","16","32","64"]'::jsonb, 2, 'Rewrite in exponential form: x = 2⁵ = 32.', 'easy'),
  ('ecele-math-algebra-q2', 'ecele', 'ecele-math', 'ecele-math-algebra', 'Simplify (3 + 4i)(3 − 4i).', '["7","25","−7","9 − 16i"]'::jsonb, 1, 'This is a difference of squares: 3² + 4² = 25 (the imaginary parts cancel).', 'medium'),
  ('ecele-math-algebra-q3', 'ecele', 'ecele-math', 'ecele-math-algebra', 'What is the exact value of sin 30°?', '["1/2","√2/2","√3/2","1"]'::jsonb, 0, 'From the standard 30-60-90 triangle, sin 30° = opposite/hypotenuse = 1/2.', 'easy'),
  ('ecele-math-calculus-q1', 'ecele', 'ecele-math', 'ecele-math-calculus', 'What is the derivative of f(x) = x³ + 2x?', '["3x² + 2","3x² + 2x","x² + 2","3x + 2"]'::jsonb, 0, 'Apply the power rule: d/dx(x³) = 3x² and d/dx(2x) = 2.', 'easy'),
  ('ecele-math-calculus-q2', 'ecele', 'ecele-math', 'ecele-math-calculus', 'Evaluate ∫ 2x dx.', '["x² + C","2 + C","x + C","2x² + C"]'::jsonb, 0, 'The antiderivative of 2x is x²; always add the constant of integration C.', 'easy'),
  ('ecele-math-calculus-q3', 'ecele', 'ecele-math', 'ecele-math-calculus', 'Find the mean of the data set {2, 4, 6, 8}.', '["4","5","6","7"]'::jsonb, 1, 'Mean = (2 + 4 + 6 + 8) / 4 = 20 / 4 = 5.', 'easy'),
  ('ecele-el-devices-q1', 'ecele', 'ecele-electronics', 'ecele-el-devices', 'What is the approximate forward voltage drop of a silicon diode?', '["0.2 V","0.3 V","0.7 V","1.4 V"]'::jsonb, 2, 'A forward-biased silicon diode typically drops about 0.7 V; germanium drops about 0.3 V.', 'easy'),
  ('ecele-el-devices-q2', 'ecele', 'ecele-electronics', 'ecele-el-devices', 'In a common-emitter BJT amplifier, what is the phase relationship between input and output?', '["0°","90°","180°","270°"]'::jsonb, 2, 'A common-emitter stage inverts the signal, producing a 180° phase shift.', 'medium'),
  ('ecele-el-devices-q3', 'ecele', 'ecele-electronics', 'ecele-el-devices', 'The current gain β of a BJT is defined as:', '["Ic / Ib","Ib / Ic","Ie / Ib","Ic / Ie"]'::jsonb, 0, 'β (hFE) is the ratio of collector current to base current.', 'medium'),
  ('ecele-el-digital-q1', 'ecele', 'ecele-electronics', 'ecele-el-digital', 'A NAND gate output is LOW only when:', '["all inputs are LOW","any input is HIGH","all inputs are HIGH","inputs are equal"]'::jsonb, 2, 'NAND is the inverse of AND: it is LOW only when every input is HIGH.', 'easy'),
  ('ecele-el-digital-q2', 'ecele', 'ecele-electronics', 'ecele-el-digital', 'Using Boolean algebra, A + Ā equals:', '["0","1","A","Ā"]'::jsonb, 1, 'The complement law states that a variable ORed with its complement always equals 1.', 'easy'),
  ('ecele-el-digital-q3', 'ecele', 'ecele-electronics', 'ecele-el-digital', 'How many distinct values can a 4-bit binary word represent?', '["8","15","16","32"]'::jsonb, 2, 'An n-bit word represents 2ⁿ values, so 2⁴ = 16 (0 through 15).', 'easy'),
  ('ecele-em-fields-q1', 'ecele', 'ecele-emag', 'ecele-em-fields', 'What is the approximate speed of an electromagnetic wave in free space?', '["3 × 10⁶ m/s","3 × 10⁸ m/s","3 × 10¹⁰ m/s","1.5 × 10⁸ m/s"]'::jsonb, 1, 'The speed of light in vacuum is approximately 3 × 10⁸ m/s.', 'easy'),
  ('ecele-em-fields-q2', 'ecele', 'ecele-emag', 'ecele-em-fields', 'A wave has a frequency of 100 MHz. What is its wavelength in free space?', '["0.3 m","3 m","30 m","300 m"]'::jsonb, 1, 'λ = c / f = (3 × 10⁸) / (1 × 10⁸) = 3 m.', 'medium'),
  ('ecele-em-fields-q3', 'ecele', 'ecele-emag', 'ecele-em-fields', 'The SI unit of magnetic flux density (B) is the:', '["Weber","Tesla","Henry","Gauss"]'::jsonb, 1, 'Magnetic flux density is measured in tesla (T); weber is the unit of flux.', 'easy'),
  ('ecele-em-transmission-q1', 'ecele', 'ecele-emag', 'ecele-em-transmission', 'The physical length of a half-wave dipole antenna is approximately:', '["λ/4","λ/2","λ","2λ"]'::jsonb, 1, 'A half-wave dipole is about half a wavelength long (≈ 0.47λ with end effects).', 'medium'),
  ('ecele-em-transmission-q2', 'ecele', 'ecele-emag', 'ecele-em-transmission', 'For a lossless transmission line, the characteristic impedance is:', '["Zo = √(L/C)","Zo = √(C/L)","Zo = L/C","Zo = LC"]'::jsonb, 0, 'The lossless line impedance is Zo = √(L/C), purely real.', 'medium'),
  ('ecele-em-transmission-q3', 'ecele', 'ecele-emag', 'ecele-em-transmission', 'A VSWR of exactly 1 indicates:', '["a complete mismatch","a perfect match","a short circuit","an open circuit"]'::jsonb, 1, 'VSWR = 1 means no reflected wave — the load is perfectly matched to the line.', 'easy'),
  ('ecele-comm-analog-q1', 'ecele', 'ecele-comm', 'ecele-comm-analog', 'For an AM wave, the modulation index m is given by:', '["(Emax − Emin) / (Emax + Emin)","(Emax + Emin) / (Emax − Emin)","Emax / Emin","Emin / Emax"]'::jsonb, 0, 'The modulation index is computed from the envelope maxima and minima.', 'medium'),
  ('ecele-comm-analog-q2', 'ecele', 'ecele-comm', 'ecele-comm-analog', 'Which modulation scheme keeps the carrier amplitude constant?', '["AM","FM","ASK","PAM"]'::jsonb, 1, 'Frequency modulation varies frequency while the amplitude remains constant.', 'easy'),
  ('ecele-comm-analog-q3', 'ecele', 'ecele-comm', 'ecele-comm-analog', 'According to the Nyquist sampling theorem, the sampling frequency must be:', '["equal to fm","at least 2fm","at most 2fm","half of fm"]'::jsonb, 1, 'To avoid aliasing, fs must be at least twice the highest message frequency.', 'easy'),
  ('ecele-comm-digital-q1', 'ecele', 'ecele-comm', 'ecele-comm-digital', 'The theoretical minimum bandwidth for binary baseband signalling at bit rate Rb is:', '["Rb","Rb/2","2Rb","4Rb"]'::jsonb, 1, 'Nyquist’s criterion gives a minimum bandwidth of Rb/2 Hz for ideal binary signalling.', 'hard'),
  ('ecele-comm-digital-q2', 'ecele', 'ecele-comm', 'ecele-comm-digital', 'An IPv4 address consists of:', '["16 bits","32 bits","64 bits","128 bits"]'::jsonb, 1, 'IPv4 uses 32-bit addresses, usually written in dotted-decimal notation.', 'easy'),
  ('ecele-comm-digital-q3', 'ecele', 'ecele-comm', 'ecele-comm-digital', 'A bit error rate of 10⁻⁶ means:', '["1 error per 10 bits","1 error per 1,000 bits","1 error per 1,000,000 bits","1 error per 100 bits"]'::jsonb, 2, 'BER is the ratio of erroneous bits to total transmitted bits, so 10⁻⁶ = 1 in a million.', 'medium'),
  ('ecele-ckt-dc-q1', 'ecele', 'ecele-circuits', 'ecele-ckt-dc', 'A 12 V source is connected to a 4 Ω resistor. What is the current?', '["2 A","3 A","4 A","48 A"]'::jsonb, 1, 'By Ohm’s law, I = V / R = 12 / 4 = 3 A.', 'easy'),
  ('ecele-ckt-dc-q2', 'ecele', 'ecele-circuits', 'ecele-ckt-dc', 'Two resistors of 4 Ω and 6 Ω connected in series have an equivalent resistance of:', '["2.4 Ω","10 Ω","5 Ω","24 Ω"]'::jsonb, 1, 'Series resistances add directly: 4 + 6 = 10 Ω.', 'easy'),
  ('ecele-ckt-dc-q3', 'ecele', 'ecele-circuits', 'ecele-ckt-dc', 'The power dissipated by a 2 Ω resistor carrying 3 A is:', '["6 W","12 W","18 W","36 W"]'::jsonb, 2, 'P = I²R = 3² × 2 = 18 W.', 'medium'),
  ('ecele-ckt-ac-q1', 'ecele', 'ecele-circuits', 'ecele-ckt-ac', 'For a sinusoid with peak voltage Vp, the RMS voltage is:', '["Vp / 2","Vp / √2","Vp × √2","Vp"]'::jsonb, 1, 'Vrms = Vp / √2 ≈ 0.707 Vp for a sine wave.', 'easy'),
  ('ecele-ckt-ac-q2', 'ecele', 'ecele-circuits', 'ecele-ckt-ac', 'In a purely capacitive AC circuit, the current:', '["leads voltage by 90°","lags voltage by 90°","is in phase with voltage","leads by 180°"]'::jsonb, 0, 'For a capacitor, current leads voltage by 90° (ICE).', 'medium'),
  ('ecele-ckt-ac-q3', 'ecele', 'ecele-circuits', 'ecele-ckt-ac', 'Series resonance in an RLC circuit occurs when:', '["XL > XC","XL < XC","XL = XC","R = 0"]'::jsonb, 2, 'At resonance the inductive and capacitive reactances cancel: XL = XC.', 'medium'),
  ('ecele-econ-interest-q1', 'ecele', 'ecele-econ', 'ecele-econ-interest', 'The simple interest on ₱1,000 at 10% per year for 2 years is:', '["₱100","₱200","₱220","₱1,200"]'::jsonb, 1, 'I = P × r × t = 1000 × 0.10 × 2 = ₱200.', 'easy'),
  ('ecele-econ-interest-q2', 'ecele', 'ecele-econ', 'ecele-econ-interest', 'An annuity is best described as:', '["a single lump-sum payment","a series of equal payments at equal intervals","a one-time investment","an irregular cash inflow"]'::jsonb, 1, 'An annuity is a sequence of equal payments made at regular time intervals.', 'easy'),
  ('ecele-econ-interest-q3', 'ecele', 'ecele-econ', 'ecele-econ-interest', 'At 8% simple interest per year, money will double in approximately:', '["8 years","10 years","12.5 years","16 years"]'::jsonb, 2, 'Doubling requires I = P, so t = 1 / 0.08 = 12.5 years.', 'medium'),
  ('ecele-econ-ethics-q1', 'ecele', 'ecele-econ', 'ecele-econ-ethics', 'The foremost obligation of an engineer under a code of ethics is to:', '["maximize profit","hold paramount the safety, health and welfare of the public","follow client instructions blindly","minimize project time"]'::jsonb, 1, 'Engineering codes of ethics place public safety, health and welfare above all else.', 'easy'),
  ('ecele-econ-ethics-q2', 'ecele', 'ecele-econ', 'ecele-econ-ethics', 'Bid rigging among competing contractors is:', '["standard practice","unethical and illegal","allowed if the client agrees","a form of value engineering"]'::jsonb, 1, 'Bid rigging is collusion that suppresses competition and is both unethical and illegal.', 'medium'),
  ('ecele-econ-ethics-q3', 'ecele', 'ecele-econ', 'ecele-econ-ethics', 'Continuing professional development is generally required for:', '["licensure renewal","getting a first job","graduation","internship"]'::jsonb, 0, 'PRC requires CPD credits as a condition for renewal of professional licenses.', 'easy'),
  ('ectle-basics-components-q1', 'ectle', 'ectle-basics', 'ectle-basics-components', 'A resistor with colour bands brown–black–red has a resistance of:', '["100 Ω","1 kΩ","10 kΩ","100 kΩ"]'::jsonb, 1, 'Brown = 1, black = 0, red = ×100, giving 10 × 100 = 1,000 Ω = 1 kΩ.', 'medium'),
  ('ectle-basics-components-q2', 'ectle', 'ectle-basics', 'ectle-basics-components', 'Which component stores energy in an electric field?', '["Resistor","Capacitor","Inductor","Diode"]'::jsonb, 1, 'A capacitor stores energy in the electric field between its plates.', 'easy'),
  ('ectle-basics-components-q3', 'ectle', 'ectle-basics', 'ectle-basics-components', 'Which component opposes changes in current flow?', '["Capacitor","Inductor","Resistor","LED"]'::jsonb, 1, 'An inductor resists changes in current by inducing a opposing voltage.', 'medium'),
  ('ectle-basics-semi-q1', 'ectle', 'ectle-basics', 'ectle-basics-semi', 'A PN junction diode conducts when it is:', '["forward biased","reverse biased","unbiased","at breakdown always"]'::jsonb, 0, 'Forward bias lowers the barrier potential and allows current to flow.', 'easy'),
  ('ectle-basics-semi-q2', 'ectle', 'ectle-basics', 'ectle-basics-semi', 'In an NPN transistor, the arrow on the emitter points:', '["toward the base","outward, away from the base","inward, toward the base","there is no arrow"]'::jsonb, 1, 'The NPN arrow points outward — “Not Pointing iN”.', 'medium'),
  ('ectle-basics-semi-q3', 'ectle', 'ectle-basics', 'ectle-basics-semi', 'A Zener diode is primarily used for:', '["amplification","voltage regulation","rectification only","light emission"]'::jsonb, 1, 'Zener diodes operate in reverse breakdown to maintain a reference voltage.', 'medium'),
  ('ectle-dig-logic-q1', 'ectle', 'ectle-digital', 'ectle-dig-logic', 'The output of an OR gate is HIGH when:', '["all inputs are LOW","at least one input is HIGH","inputs are different","all inputs are HIGH only"]'::jsonb, 1, 'An OR gate outputs HIGH if any input is HIGH.', 'easy'),
  ('ectle-dig-logic-q2', 'ectle', 'ectle-digital', 'ectle-dig-logic', 'An XOR gate outputs 1 when:', '["both inputs are 0","both inputs are 1","the inputs are different","either input is 1"]'::jsonb, 2, 'XOR (exclusive OR) is true only when the inputs differ.', 'easy'),
  ('ectle-dig-logic-q3', 'ectle', 'ectle-digital', 'ectle-dig-logic', 'De Morgan’s theorem states that (A·B)′ equals:', '["A′·B′","A′ + B′","A + B","A·B"]'::jsonb, 1, 'De Morgan: the complement of a product equals the sum of the complements.', 'medium'),
  ('ectle-dig-systems-q1', 'ectle', 'ectle-digital', 'ectle-dig-systems', 'The binary number 1010 is equal to the decimal value:', '["8","9","10","12"]'::jsonb, 2, '1010₂ = 8 + 0 + 2 + 0 = 10.', 'easy'),
  ('ectle-dig-systems-q2', 'ectle', 'ectle-digital', 'ectle-dig-systems', 'The hexadecimal digit F represents the decimal value:', '["10","14","15","16"]'::jsonb, 2, 'Hex digits run 0–9 then A=10 through F=15.', 'easy'),
  ('ectle-dig-systems-q3', 'ectle', 'ectle-digital', 'ectle-dig-systems', 'One byte consists of:', '["4 bits","8 bits","16 bits","32 bits"]'::jsonb, 1, 'A byte is 8 bits and can represent 256 distinct values.', 'easy'),
  ('ectle-elec-dc-q1', 'ectle', 'ectle-electrical', 'ectle-elec-dc', 'An ammeter must be connected:', '["in parallel with the load","in series with the load","across the supply only","to ground only"]'::jsonb, 1, 'An ammeter measures current and must be placed in series so the same current flows through it.', 'easy'),
  ('ectle-elec-dc-q2', 'ectle', 'ectle-electrical', 'ectle-elec-dc', 'A good voltmeter has:', '["very low internal resistance","very high internal resistance","zero internal resistance","no internal resistance"]'::jsonb, 1, 'High internal resistance minimises the current drawn from the circuit under test.', 'medium'),
  ('ectle-elec-dc-q3', 'ectle', 'ectle-electrical', 'ectle-elec-dc', 'The power dissipated in a resistor can be computed as:', '["P = V × I","P = I²R","P = V²/R","All of the above"]'::jsonb, 3, 'All three expressions are equivalent via Ohm’s law.', 'easy'),
  ('ectle-elec-ac-q1', 'ectle', 'ectle-electrical', 'ectle-elec-ac', 'The standard mains frequency in the Philippines is:', '["50 Hz","60 Hz","100 Hz","400 Hz"]'::jsonb, 1, 'Philippine mains power is nominally 220 V at 60 Hz.', 'easy'),
  ('ectle-elec-ac-q2', 'ectle', 'ectle-electrical', 'ectle-elec-ac', 'The RMS value of a 220 V AC mains rating refers to:', '["peak voltage","average voltage","effective voltage","peak-to-peak voltage"]'::jsonb, 2, 'AC voltage ratings are normally RMS (effective) values.', 'medium'),
  ('ectle-elec-ac-q3', 'ectle', 'ectle-electrical', 'ectle-elec-ac', 'Power factor is defined as:', '["the ratio of real to apparent power","the ratio of apparent to real power","the sine of the phase angle","the supply frequency"]'::jsonb, 0, 'PF = cos φ = real power / apparent power.', 'medium'),
  ('ectle-comm-radio-q1', 'ectle', 'ectle-comm', 'ectle-comm-radio', 'Modulation is the process of:', '["amplifying a carrier","varying a carrier with an information signal","filtering noise only","converting AC to DC"]'::jsonb, 1, 'Modulation impresses information onto a high-frequency carrier for transmission.', 'easy'),
  ('ectle-comm-radio-q2', 'ectle', 'ectle-comm', 'ectle-comm-radio', 'The standard AM broadcast band extends approximately from:', '["530 to 1700 kHz","88 to 108 MHz","3 to 30 MHz","1 to 2 GHz"]'::jsonb, 0, 'The AM broadcast band is roughly 530–1700 kHz (medium wave).', 'medium'),
  ('ectle-comm-radio-q3', 'ectle', 'ectle-comm', 'ectle-comm-radio', 'A quarter-wave antenna at 100 MHz is approximately:', '["0.075 m","0.75 m","3 m","7.5 m"]'::jsonb, 1, 'λ = 3 m at 100 MHz, so λ/4 = 0.75 m.', 'medium'),
  ('ectle-comm-data-q1', 'ectle', 'ectle-comm', 'ectle-comm-data', 'The connector most commonly used for twisted-pair Ethernet is:', '["RJ11","RJ45","BNC","USB-C"]'::jsonb, 1, 'Ethernet over twisted pair uses an 8-position RJ45 connector.', 'easy'),
  ('ectle-comm-data-q2', 'ectle', 'ectle-comm', 'ectle-comm-data', 'A network hub operates at which OSI layer?', '["Physical","Data Link","Network","Transport"]'::jsonb, 0, 'A hub simply repeats electrical signals and works at the physical layer.', 'medium'),
  ('ectle-comm-data-q3', 'ectle', 'ectle-comm', 'ectle-comm-data', 'Category 5e cable supports data rates up to:', '["10 Mbps","100 Mbps","1 Gbps","10 Gbps"]'::jsonb, 2, 'Cat5e is specified for Gigabit Ethernet (1000BASE-T) up to 100 m.', 'medium'),
  ('ectle-ind-control-q1', 'ectle', 'ectle-industrial', 'ectle-ind-control', 'A relay is best described as:', '["a solid-state amplifier","an electrically operated switch","a voltage regulator","a current source"]'::jsonb, 1, 'A relay uses an electromagnet to open or close contacts, isolating control from load.', 'easy'),
  ('ectle-ind-control-q2', 'ectle', 'ectle-industrial', 'ectle-ind-control', 'The synchronous speed of an induction motor depends on:', '["supply frequency and number of poles","load torque only","armature resistance","ambient temperature"]'::jsonb, 0, 'Ns = 120f / P, so speed depends on frequency and pole count.', 'medium'),
  ('ectle-ind-control-q3', 'ectle', 'ectle-industrial', 'ectle-ind-control', 'PLC stands for:', '["Programmable Logic Controller","Power Line Conduit","Personal Logic Circuit","Programmed Load Control"]'::jsonb, 0, 'A PLC is a ruggedised digital computer used for industrial automation.', 'easy'),
  ('ectle-ind-safety-q1', 'ectle', 'ectle-industrial', 'ectle-ind-safety', 'Before servicing electrical equipment, you should first:', '["remove the fuse only","disconnect and lock out the power supply","wear thin gloves","increase the load"]'::jsonb, 1, 'Lockout/tagout and de-energising the circuit is the essential first safety step.', 'easy'),
  ('ectle-ind-safety-q2', 'ectle', 'ectle-industrial', 'ectle-ind-safety', 'A fuse primarily protects a circuit against:', '["overvoltage","overcurrent","low frequency","reverse polarity"]'::jsonb, 1, 'A fuse opens the circuit when current exceeds its rated value.', 'easy'),
  ('ectle-ind-safety-q3', 'ectle', 'ectle-industrial', 'ectle-ind-safety', 'Equipping metal enclosures with a safety ground helps prevent:', '["electric shock","voltage sag","radio interference","power factor penalty"]'::jsonb, 0, 'Grounding provides a low-resistance fault path so protective devices trip quickly.', 'medium'),
  ('ectle-prac-soldering-q1', 'ectle', 'ectle-practical', 'ectle-prac-soldering', 'Traditional solder is an alloy mainly of:', '["copper and zinc","tin and lead","silver and gold","aluminium and iron"]'::jsonb, 1, 'Conventional solder is a tin-lead alloy; lead-free variants use tin with silver/copper.', 'easy'),
  ('ectle-prac-soldering-q2', 'ectle', 'ectle-practical', 'ectle-prac-soldering', 'Before use, the tip of a soldering iron should be:', '["painted","tinned","sandblasted","oiled"]'::jsonb, 1, 'Tinning the tip with solder improves heat transfer and prevents oxidation.', 'medium'),
  ('ectle-prac-soldering-q3', 'ectle', 'ectle-practical', 'ectle-prac-soldering', 'On an IC package, the notch or dot identifies:', '["pin 1","the last pin","ground only","the negative supply"]'::jsonb, 0, 'The notch/dot marks pin 1 and the pins are then counted counter-clockwise.', 'medium'),
  ('ectle-prac-instruments-q1', 'ectle', 'ectle-practical', 'ectle-prac-instruments', 'An oscilloscope primarily displays:', '["current versus temperature","voltage versus time","resistance versus frequency","power versus time"]'::jsonb, 1, 'An oscilloscope plots instantaneous voltage on the vertical axis against time horizontally.', 'easy'),
  ('ectle-prac-instruments-q2', 'ectle', 'ectle-practical', 'ectle-prac-instruments', 'A digital multimeter can typically measure:', '["voltage, current and resistance","only voltage","only current","frequency only"]'::jsonb, 0, 'The common DMM measures volts, amps and ohms, often with extra functions.', 'easy'),
  ('ectle-prac-instruments-q3', 'ectle', 'ectle-practical', 'ectle-prac-instruments', 'A function generator is used to produce:', '["DC power only","test waveforms such as sine and square","high-voltage transmission","mechanical rotation"]'::jsonb, 1, 'Function generators create repeatable test signals at adjustable frequency and amplitude.', 'easy')
